SELECT DISTINCT new_status_id FROM workflow_transition
WHERE


        project_id = #{projectId}


        project_id IS NULL


  AND issue_type = #{issueType}
  AND role_id IN

    #{roleId}

  AND old_status_id = #{oldStatusId}
  AND (
    (author = false AND assignee = false)

        OR (author = true)


        OR (assignee = true)

  )
ORDER BY new_status_id

SELECT DISTINCT new_status_id, CASE WHEN project_id = #{projectId} AND issue_type = #{issueType} THEN 1 WHEN project_id = #{projectId} AND issue_type = '*' THEN 2 WHEN project_id IS NULL AND issue_type = #{issueType} THEN 3 WHEN project_id IS NULL AND issue_type = '*' THEN 4 END AS priority_level, conditions, id AS transition_id FROM workflow_transition WHERE (project_id = #{projectId} OR project_id IS NULL) AND (issue_type = #{issueType} OR issue_type = '*') AND role_id IN
#{roleId}
AND old_status_id = #{oldStatusId} AND ( (author = false AND assignee = false)
OR (author = true)
OR (assignee = true)
) ORDER BY priority_level, new_status_id

SELECT DISTINCT old_status_id FROM workflow_transition
WHERE


        project_id = #{projectId}


        project_id IS NULL


  AND role_id IN

    #{roleId}
